mapper.select:
SELECT DATE_FORMAT(pi.create_time, '%Y-%m-%d') AS date, COUNT(*) AS total, SUM(CASE WHEN pi.status = '识别成功' THEN 1 ELSE 0 END) AS successNum FROM plate_identify pi WHERE pi.deleted = 0 AND pi.create_time >= FROM_UNIXTIME(#{startTime}) AND pi.create_time <= FROM_UNIXTIME(#{endTime})
AND pi.station_id = #{stationId}
GROUP BY DATE_FORMAT(pi.create_time, '%Y-%m-%d') ORDER BY date

SELECT s.name AS stationName, COUNT(*) AS count FROM plate_identify pi INNER JOIN station_info s ON pi.station_id = s.id WHERE pi.deleted = 0 AND pi.create_time >= FROM_UNIXTIME(#{startTime}) AND pi.create_time <= FROM_UNIXTIME(#{endTime})
AND pi.station_id = #{stationId}
GROUP BY pi.station_id, s.name ORDER BY count DESC
